#!/usr/bin/env python3
"""Reconstruct reviewed 1.1.2 sources from immutable-hash-checked 1.1.1 inputs.
No feed is updated by this preparation step. Runtime/application tests follow in CI.
"""
from pathlib import Path, PurePosixPath
import base64,hashlib,json,lzma
ROOT=Path('releases/homeback112')
DATA=""""""
raw=base64.b64decode(DATA,validate=True)
assert hashlib.sha256(raw).hexdigest()=='1efacfb44a029b3349dd8b8dc5f1865bc741f7a3712f8b12cd868d1cc5d3b9b8','Transport integrity failure'
rows=json.loads(lzma.decompress(raw))
assert len(rows)==52
for name,row in rows.items():
 p=PurePosixPath(name)
 assert not p.is_absolute() and '..' not in p.parts and str(p)==name and '\\' not in name
 target=ROOT/p
 assert not target.exists(), 'Unexpected existing target '+name
 if 'text' in row:data=row['text'].encode('utf-8')
 else:
  source=Path(row.get('copy') or row['base'])
  assert str(source).startswith(('releases/homeback111/','releases/oneback163/src/'))
  data=source.read_bytes()
  assert hashlib.sha256(data).hexdigest()==row['sha'],'Baseline source changed: '+str(source)
  if 'edits' in row:
   lines=data.decode('utf-8').splitlines(True)
   for start,end,replacement in reversed(row['edits']):
    assert 0<=start<=end<=len(lines)
    lines[start:end]=replacement
   data=''.join(lines).encode('utf-8')
 target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data)
print('PASS reconstructed reviewed Back112 sources:',len(rows))
